import os, sys, math
sys.path.insert(0, os.path.join(os.path.dirname(__file__), '..', 'author'))
from _lib import *
G = Gen('m07', 16, 20250707, dict(fb=('Feedback oscillator conditions', 'Điều kiện của mạch dao động hồi tiếp'), rc=('RC oscillators', 'Mạch dao động RC'), lc=('LC and crystal oscillators', 'Mạch dao động LC và thạch anh'), rx=('Relaxation oscillators', 'Mạch dao động thư giãn'), t555=('The 555 timer', 'IC định thời 555')))
g, fmt, add = G.g, G.fmt, G.add; S = lambda a, b: (a, b)
def hz(x): return f'{x/1e6:.3g} MHz' if x >= 1e6 else (f'{x/1e3:.3g} kHz' if x >= 1e3 else f'{x:.3g} Hz')
def tm(x): return f'{x*1e3:.3g} ms' if x >= 1e-3 else f'{x*1e6:.3g} μs'
for r, c in [(6.2, 0.02), (10, 0.01), (4.7, 0.022), (1.0, 0.1), (15, 0.0047), (22, 0.033)]:
    fr = 1 / (2 * math.pi * r * 1e3 * c * 1e-6)
    add('rc', f'A Wien-bridge lead-lag network has R1 = R2 = {r} kΩ and C1 = C2 = {c} μF. What is the resonant frequency?', f'Mạng sớm–trễ của cầu Wien có R1 = R2 = {r} kΩ và C1 = C2 = {c} μF. Tần số cộng hưởng là bao nhiêu?', hz(fr), [hz(fr * 2 * math.pi), hz(fr / math.sqrt(6)), hz(fr * 2), hz(fr / 2 / math.pi)], f'fr = 1/(2πRC) = {hz(fr)}.', f'fr = 1/(2πRC) = {hz(fr)}.', S('Floyd Problem 6', 'Floyd Bài 6'), 2)
for f_, c in [(1000, 0.01), (5000, 0.0047), (60, 0.33), (20e3, 0.001)]:
    r = 1 / (2 * math.pi * f_ * c * 1e-6); rr = lambda x: f'{x/1e3:.3g} kΩ' if x >= 1e3 else f'{x:.3g} Ω'
    add('rc', f'What R (R1 = R2) gives a Wien-bridge oscillator fr = {hz(f_)} with C1 = C2 = {c} μF?', f'R (R1 = R2) bằng bao nhiêu để mạch cầu Wien có fr = {hz(f_)} với C1 = C2 = {c} μF?', rr(r), [rr(r * 2 * math.pi), rr(r / 2 / math.pi), rr(1 / (f_ * c * 1e-6)), rr(r / 2)], f'R = 1/(2π·fr·C) = {rr(r)}.', f'R = 1/(2π·fr·C) = {rr(r)}.', S('Floyd Problem 6', 'Floyd Bài 6'), 2)
for r, c in [(4.7, 0.022), (10, 0.001), (2.2, 0.01), (47, 0.0047)]:
    fr = 1 / (2 * math.pi * math.sqrt(6) * r * 1e3 * c * 1e-6)
    add('rc', f'A three-section RC phase-shift oscillator has R = {r} kΩ and C = {c} μF in each section. What is the frequency? (fr = 1/(2π√6·RC))', f'Mạch dao động dịch pha ba khâu RC có R = {r} kΩ và C = {c} μF mỗi khâu. Tần số là bao nhiêu? (fr = 1/(2π√6·RC))', hz(fr), [hz(fr * math.sqrt(6)), hz(fr * math.sqrt(6) ** 2), hz(1 / (2 * math.pi * r * 1e3 * c * 1e-6)), hz(fr / 2)], f'fr = 1/(2π√6 × {r} kΩ × {c} μF) = {hz(fr)}.', f'fr = 1/(2π√6 × {r} kΩ × {c} μF) = {hz(fr)}.', S('Floyd Problem 11', 'Floyd Bài 11'), 3)
    add('rc', f'In a phase-shift oscillator with Ri = {r} kΩ, what feedback resistor Rf is needed for the gain of 29?', f'Ở mạch dao động dịch pha có Ri = {r} kΩ, cần điện trở hồi tiếp Rf bằng bao nhiêu để độ lợi là 29?', fmt(29 * r, 'kΩ'), [fmt(r / 29, 'kΩ'), fmt(r * 3, 'kΩ'), fmt(r * 28, 'kΩ'), fmt(r * 30, 'kΩ')], f'Rf = 29·Ri = 29 × {r} = {g(29*r)} kΩ.', f'Rf = 29·Ri = 29 × {r} = {g(29*r)} kΩ.', S('Floyd Problem 11', 'Floyd Bài 11'), 2)
for av in [25, 50, 75, 100, 200]:
    add('fb', f'The amplifier of a feedback oscillator has Av = {av}. What feedback attenuation B sustains oscillation?', f'Mạch khuếch đại của dao động hồi tiếp có Av = {av}. Độ suy giảm hồi tiếp B nào duy trì dao động?', g(1 / av, 3), [g(av, 3), g(1 / av * 2, 3), g(1 / (av + 1), 3), g(av / 2, 3)], f'Av·B = 1 → B = 1/{av} = {g(1/av,3)}.', f'Av·B = 1 → B = 1/{av} = {g(1/av,3)}.', S('Floyd Self-Test Q4', 'Floyd Self-Test câu 4'))
for vin in [1.0, 2.2, 3.3, 5.0, 9.0]:
    add('rc', f'A lead-lag circuit at its resonant frequency has an input of {vin} V rms. What is the output (rms)?', f'Mạch sớm–trễ tại tần số cộng hưởng có tín hiệu vào {vin} V rms. Điện áp ra (rms) là bao nhiêu?', fmt(vin / 3, 'V'), [fmt(vin * 3, 'V'), fmt(vin / 2, 'V'), fmt(vin, 'V'), fmt(vin / 29, 'V')], f'At fr the attenuation is 1/3: {vin}/3 = {g(vin/3)} V.', f'Tại fr độ suy giảm là 1/3: {vin}/3 = {g(vin/3)} V.', S('Floyd Problem 5', 'Floyd Bài 5'))
for c1, c2, l in [(470, 47, 1), (1000, 100, 5), (220, 220, 2), (100, 1000, 1)]:
    ct = c1 * c2 / (c1 + c2); fr = 1 / (2 * math.pi * math.sqrt(l * 1e-3 * ct * 1e-12))
    add('lc', f'A Colpitts oscillator has C1 = {c1} pF, C2 = {c2} pF and L = {l} mH. What is the frequency? (fr = 1/(2π√(L·CT)), CT = C1C2/(C1+C2))', f'Mạch Colpitts có C1 = {c1} pF, C2 = {c2} pF và L = {l} mH. Tần số là bao nhiêu? (fr = 1/(2π√(L·CT)), CT = C1C2/(C1+C2))', hz(fr), [hz(1 / (2 * math.pi * math.sqrt(l * 1e-3 * (c1 + c2) * 1e-12))), hz(1 / (2 * math.pi * math.sqrt(l * 1e-3 * c1 * 1e-12))), hz(fr * 2), hz(fr / 2)], f'CT = {g(ct)} pF; fr = 1/(2π√({l} mH × {g(ct)} pF)) = {hz(fr)}.', f'CT = {g(ct)} pF; fr = 1/(2π√({l} mH × {g(ct)} pF)) = {hz(fr)}.', S('Floyd Problem 12', 'Floyd Bài 12'), 3)
    add('lc', f'The feedback capacitors of a Colpitts oscillator are C1 = {c1} pF and C2 = {c2} pF. What amplifier gain sustains oscillation? (Av = C1/C2)', f'Các tụ hồi tiếp của mạch Colpitts là C1 = {c1} pF và C2 = {c2} pF. Độ lợi mạch khuếch đại nào duy trì dao động? (Av = C1/C2)', g(c1 / c2, 3), [g(c2 / c1, 3), g(c1 + c2, 3), g(c1 * c2, 3), g(c1 / c2 + 1, 3)], f'Av = C1/C2 = {c1}/{c2} = {g(c1/c2,3)}.', f'Av = C1/C2 = {c1}/{c2} = {g(c1/c2,3)}.', S('Floyd Problem 13', 'Floyd Bài 13'), 2)
for r1, r2, c in [(1.0, 3.3, 0.047), (2.2, 4.7, 0.01), (10, 47, 0.001), (4.7, 10, 0.1), (1.0, 1.0, 0.22)]:
    f_ = 1.44 / ((r1 + 2 * r2) * 1e3 * c * 1e-6); d = (r1 + r2) / (r1 + 2 * r2) * 100
    add('t555', f'A 555 astable has R1 = {r1} kΩ, R2 = {r2} kΩ and Cext = {c} μF. What is the output frequency? (f = 1.44/((R1+2R2)Cext))', f'Mạch 555 phi ổn có R1 = {r1} kΩ, R2 = {r2} kΩ và Cext = {c} μF. Tần số ngõ ra là bao nhiêu? (f = 1,44/((R1+2R2)Cext))', hz(f_), [hz(1.44 / ((r1 + r2) * 1e3 * c * 1e-6)), hz(f_ * 2), hz(1 / ((r1 + 2 * r2) * 1e3 * c * 1e-6)), hz(f_ / 2)], f'f = 1.44/(({r1}+2×{r2}) kΩ × {c} μF) = {hz(f_)}.', f'f = 1,44/(({r1}+2×{r2}) kΩ × {c} μF) = {hz(f_)}.', S('Floyd Problem 20', 'Floyd Bài 20'), 2)
    add('t555', f'A 555 astable has R1 = {r1} kΩ and R2 = {r2} kΩ. What is the duty cycle?', f'Mạch 555 phi ổn có R1 = {r1} kΩ và R2 = {r2} kΩ. Chu kỳ làm việc là bao nhiêu?', f'{d:.3g} %', [f'{(r2/(r1+2*r2)*100):.3g} %', f'{(r1/(r1+r2)*100):.3g} %', f'{((r1+2*r2)/(r1+r2)*100):.3g} %', f'{(r1/(r1+2*r2)*100):.3g} %'], f'Duty cycle = (R1+R2)/(R1+2R2) = {r1+r2:g}/{r1+2*r2:g} = {d:.3g} %.', f'Chu kỳ làm việc = (R1+R2)/(R1+2R2) = {r1+r2:g}/{r1+2*r2:g} = {d:.3g} %.', S('Floyd Problem 22', 'Floyd Bài 22'), 2)
for r, c in [(10, 0.1), (47, 0.01), (100, 1.0), (1.0, 0.47), (22, 0.22)]:
    tw = 1.1 * r * 1e3 * c * 1e-6
    add('t555', f'A 555 monostable has Rext = {r} kΩ and Cext = {c} μF. What is the output pulse width? (tW = 1.1·R·C)', f'Mạch 555 đơn ổn có Rext = {r} kΩ và Cext = {c} μF. Độ rộng xung ra là bao nhiêu? (tW = 1,1·R·C)', tm(tw), [tm(tw / 1.1), tm(tw * 1.44 / 1.1), tm(tw * 10), tm(tw / 10)], f'tW = 1.1 × {r} kΩ × {c} μF = {tm(tw)}.', f'tW = 1,1 × {r} kΩ × {c} μF = {tm(tw)}.', S('Floyd Section 16–6', 'Floyd §16–6'), 2)
for vcc in [5, 9, 10, 12, 15]:
    add('t555', f'What are the two comparator reference voltages in a 555 timer when VCC = {vcc} V?', f'Hai điện áp tham chiếu của bộ so sánh trong IC 555 khi VCC = {vcc} V là bao nhiêu?', f'{g(vcc/3)} V and {g(2*vcc/3)} V', [f'{g(vcc/2)} V and {g(vcc)} V', f'{g(vcc/4)} V and {g(3*vcc/4)} V', f'{g(vcc/3)} V and {g(vcc/2)} V', f'0 V and {g(vcc/3)} V'], f'1/3 VCC = {g(vcc/3)} V and 2/3 VCC = {g(2*vcc/3)} V.', f'1/3 VCC = {g(vcc/3)} V và 2/3 VCC = {g(2*vcc/3)} V.', S('Floyd Problem 19', 'Floyd Bài 19'))
for vin, r, c, t in [(3, 4.7, 0.001, 10), (5, 10, 0.001, 20), (2, 22, 0.0047, 50), (10, 47, 0.001, 100)]:
    vpp = vin / (r * 1e3 * c * 1e-6) * t * 1e-6
    add('rx', f'A sawtooth generator has VIN = {vin} V, R = {r} kΩ, C = {c} μF and a period of {t} μs. What is the peak-to-peak output?', f'Bộ phát răng cưa có VIN = {vin} V, R = {r} kΩ, C = {c} μF và chu kỳ {t} μs. Điện áp ra đỉnh–đỉnh là bao nhiêu?', fmt(vpp, 'V'), [fmt(vpp / 2, 'V'), fmt(vpp * 2, 'V'), fmt(vin * r * c, 'V'), fmt(vpp * 10, 'V')], f'Vpp = (VIN/RC)·T = ({vin}/({r} kΩ × {c} μF)) × {t} μs = {g(vpp)} V.', f'Vpp = (VIN/RC)·T = ({vin}/({r} kΩ × {c} μF)) × {t} μs = {g(vpp)} V.', S('Floyd Problem 18', 'Floyd Bài 18'), 3)
C = [('fb','The two conditions for sustained oscillation are','Hai điều kiện để duy trì dao động là',('loop gain of 1 and net loop phase shift of 0°','độ lợi vòng bằng 1 và độ lệch pha vòng bằng 0°'),[('loop gain of 0 and phase shift of 90°','độ lợi vòng bằng 0 và lệch pha 90°'),('loop gain of 2 and phase shift of 180°','độ lợi vòng bằng 2 và lệch pha 180°'),('no gain and no phase shift','không có độ lợi và không lệch pha')],'Barkhausen criteria.','Tiêu chuẩn Barkhausen.'),
 ('fb','The signal that starts an oscillation is','Tín hiệu khởi động dao động là',('noise or the power-on transient','nhiễu hoặc quá độ khi bật nguồn'),[('an external square wave','sóng vuông bên ngoài'),('the load current','dòng tải'),('a second oscillator','một mạch dao động khác')],'Loop gain > 1 amplifies tiny disturbances.','Độ lợi vòng > 1 khuếch đại các nhiễu rất nhỏ.'),
 ('rc','In a Wien-bridge oscillator, the amplifier gain needed at fr is','Ở mạch cầu Wien, độ lợi cần có của mạch khuếch đại tại fr là',('3','3'),[('1/3','1/3'),('29','29'),('1','1')],'The lead-lag attenuation is 1/3, so Av = 3.','Mạng sớm–trễ suy giảm 1/3 nên Av = 3.'),
 ('rc','A phase-shift oscillator needs an amplifier gain of at least','Mạch dao động dịch pha cần mạch khuếch đại có độ lợi tối thiểu',('29','29'),[('3','3'),('1','1'),('100','100')],'Three RC sections attenuate by 1/29 at fr.','Ba khâu RC suy giảm 1/29 tại fr.'),
 ('rc','The JFET (or lamp/zener) in a Wien-bridge oscillator is used to','JFET (hoặc đèn/zener) trong mạch cầu Wien dùng để',('stabilize the amplitude by controlling the gain','ổn định biên độ bằng cách điều khiển độ lợi'),[('set the frequency','đặt tần số'),('provide phase shift','tạo độ lệch pha'),('supply bias to the crystal','cấp phân cực cho thạch anh')],'The gain falls as the output amplitude rises, preventing clipping.','Độ lợi giảm khi biên độ ra tăng, tránh xén.'),
 ('lc','A crystal oscillator is chosen when the main requirement is','Chọn dao động thạch anh khi yêu cầu chính là',('frequency stability','độ ổn định tần số'),[('low cost','chi phí thấp'),('wide tuning range','dải điều chỉnh rộng'),('low frequency only','chỉ tần số thấp')],'Quartz resonance is extremely stable.','Cộng hưởng thạch anh cực kỳ ổn định.'),
 ('lc','A Colpitts oscillator uses a tank with','Mạch Colpitts dùng mạch cộng hưởng gồm',('two capacitors and an inductor','hai tụ điện và một cuộn cảm'),[('two inductors and a capacitor','hai cuộn cảm và một tụ điện'),('three resistors','ba điện trở'),('a crystal and a resistor','một thạch anh và một điện trở')],'The capacitive divider provides the feedback fraction.','Bộ chia điện dung tạo tỉ lệ hồi tiếp.'),
 ('lc','A Hartley oscillator differs from a Colpitts in that it uses','Mạch Hartley khác Colpitts ở chỗ nó dùng',('a tapped inductor (two inductors) and one capacitor','cuộn cảm có đầu ra giữa (hai cuộn cảm) và một tụ điện'),[('two capacitors and one inductor','hai tụ điện và một cuộn cảm'),('a crystal','thạch anh'),('only resistors','chỉ điện trở')],'Inductive feedback divider instead of capacitive.','Bộ chia hồi tiếp điện cảm thay vì điện dung.'),
 ('rx','A relaxation oscillator typically produces','Mạch dao động thư giãn thường tạo ra',('a nonsinusoidal waveform','dạng sóng không sin'),[('a pure sine wave','sóng sin thuần'),('a dc level','mức một chiều'),('white noise','nhiễu trắng')],'Square, triangular or sawtooth waves.','Sóng vuông, tam giác hoặc răng cưa.'),
 ('rx','In a triangular-wave generator made of a comparator and an integrator, the comparator output is a','Trong bộ phát sóng tam giác gồm mạch so sánh và mạch tích phân, ngõ ra mạch so sánh là',('square wave','sóng vuông'),[('triangular wave','sóng tam giác'),('sine wave','sóng sin'),('dc level','mức một chiều')],'The integrator turns the square wave into a triangle.','Mạch tích phân biến sóng vuông thành tam giác.'),
 ('t555','The 555 discharge transistor is used to','Transistor xả của 555 dùng để',('discharge the external timing capacitor','xả tụ định thời ngoài'),[('amplify the output','khuếch đại ngõ ra'),('set VCC','đặt VCC'),('generate the reference voltages','tạo các điện áp tham chiếu')],'It shorts the capacitor to ground when the flip-flop is set.','Nó nối tụ xuống đất khi flip-flop được đặt.'),
 ('t555','In a 555 monostable, the output pulse is started by','Ở 555 đơn ổn, xung ra được khởi phát bởi',('a trigger input falling below 1/3 VCC','ngõ trigger giảm xuống dưới 1/3 VCC'),[('the threshold rising above 2/3 VCC','ngưỡng tăng lên trên 2/3 VCC'),('the reset pin','chân reset'),('the control pin','chân điều khiển')],'The lower comparator sets the flip-flop.','Bộ so sánh dưới đặt flip-flop.')]
